<div class="page-heading"><div><div class="breadcrumb-line">Home <span>&rsaquo;</span> Stock / Parts <span>&rsaquo;</span> <b>Stock View</b></div><h1><?= e($item['part_name']) ?></h1><p><?= e($item['part_code']) ?> | <?= e($item['brand']?:'-') ?></p></div><a class="btn btn-danger" href="index.php?page=admin&amp;section=stock-restock&amp;id=<?= (int)$item['id'] ?>">+ Restock Item</a></div><div class="admin-panel stock-list"><div class="row g-3"><div class="col-md-3"><small>Current Stock</small><h3><?= number_format((float)$item['stock_qty'],2) ?> <?= e($item['unit']) ?></h3></div><div class="col-md-3"><small>Buying Price</small><h3>Rs. <?= number_format((float)$item['buying_price'],2) ?></h3></div><div class="col-md-3"><small>Selling Price</small><h3>Rs. <?= number_format((float)$item['selling_price'],2) ?></h3></div><div class="col-md-3"><small>Reorder Level</small><h3><?= number_format((float)$item['reorder_level'],2) ?></h3></div></div><h2 class="mt-4">Purchase / Batch History</h2><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Batch No.</th><th>Date</th><th>Supplier</th><th>Received</th><th>Remaining</th><th>Buying Price</th><th>Invoice</th></tr></thead><tbody><?php foreach($batches as $batch): ?><tr><td><?= e($batch['batch_reference']?:'BATCH-'.$batch['id']) ?></td><td><?= e($batch['purchase_date']) ?></td><td><?= e($batch['supplier_name']?:'-') ?></td><td><?= number_format((float)$batch['quantity_received'],2) ?></td><td><?= number_format((float)$batch['quantity_remaining'],2) ?></td><td><?= number_format((float)$batch['buying_price'],2) ?></td><td><?= e($batch['invoice_no']?:'-') ?></td></tr><?php endforeach; ?></tbody></table></div><h2 class="mt-4">Stock Movement History</h2><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Date</th><th>Movement</th><th>Qty In</th><th>Before</th><th>After</th><th>Unit Cost</th><th>User</th></tr></thead><tbody><?php foreach($movements as $movement): ?><tr><td><?= e($movement['created_at']) ?></td><td><?= e(ucwords(str_replace('_',' ',$movement['movement_type']))) ?></td><td><?= number_format((float)$movement['quantity'],2) ?></td><td><?= number_format((float)$movement['quantity_before'],2) ?></td><td><?= number_format((float)$movement['quantity_after'],2) ?></td><td><?= number_format((float)$movement['unit_cost'],2) ?></td><td><?= e($movement['user_name']?:'-') ?></td></tr><?php endforeach; ?></tbody></table></div></div>
